extern "C" __global__ void solve(const float* a, const float* b, float* out, int n) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        out[i] = a[i] - b[i];
    }
}

extern "C" __global__ void solve(const float* a, const float* b, float* out, int n) {
    int i = threadIdx.x;
    if (i < n) {
        out[i] = a[i] + b[i];
    }
}

extern "C" __global__ void solve(const float* a, const float* b, float* out, int n) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) {
        out[i] = float(int(a[i]) + int(b[i]));
    }
}

cuda-matrix-product.source:
extern "C" __global__ void solve(const float* a, const float* b, float* out, int m, int n, int k) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int column = blockIdx.x * blockDim.x + threadIdx.x;
    if (row < m && column < n) {
        float value = 0.0f;
        for (int inner = 0; inner < k; ++inner) {
            value += a[row * k + inner] * b[column * k + inner];
        }
        out[row * n + column] = value;
    }
}

extern "C" __global__ void solve(const float* a, const float* b, float* out, int m, int n, int k) {
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int column = blockIdx.x * blockDim.x + threadIdx.x;
    if (row < m && column < n) {
        float value = 0.0f;
        for (int inner = 0; inner < k && inner < m; ++inner) {
            value += a[row * k + inner] * b[inner * n + column];
        }
        out[row * n + column] = value;
    }
}

extern "C" __global__ void solve(const float* a, const float* b, float* out, int m, int n, int k) {
    int row = threadIdx.y;
    int column = threadIdx.x;
    if (row < m && column < n) {
        float value = 0.0f;
        for (int inner = 0; inner < k; ++inner) {
            value += a[row * k + inner] * b[inner * n + column];
        }
        out[row * n + column] = value;
    }
}
